head.script:
/************************************************************************************
 * ID           :    ULDSTF92025
 * File         :    ULDSTF92025.xml
 * Name         :    (팝업)의무보유 등록/수정
 * Author       :    배성우
 * Description  :
 * Create Date  :    2026-09-03
 * Modify       :  YOO
 ************************************************************************************/

scwin.market = String($c.session.getUserInfo("market") ?? "");

scwin.BTN_MAP = {
    "save": "btn_save",
    "delete": "btn_delete",
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92025.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function () {
};

/**
 * @method
 * @name init
 * @description 화면 초기화
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    await scwin.searchCode();
    scwin.getParam = $c.data.getParameter();
    scwin.parentWin = $c.win.getParent();
    scwin.gRow = scwin.parentWin.scwin.gPrtdepoSeq;
    scwin.gDtsObj = scwin.parentWin.dlt_PRTDEPO;

    const parentIsuKorNm = $c.util.isEmpty(scwin.parentWin.txb_ISU_KOR_NM) ? "" : scwin.parentWin.txb_ISU_KOR_NM.getValue();
    if (parentIsuKorNm === "") {
        ibx_isuNm.setValue(scwin.getParam.isuKorNm);
    } else {
        ibx_isuNm.setValue(parentIsuKorNm);
    }

    // 부모창에 따라 보여주기 변경
    if (scwin.parentWin.pMenuID === "ULDSTF05200" || scwin.parentWin.pMenuID === "ULDSTF05201") {
        sbx_prtdepoYn.show("");
    } else {
        sbx_prtdepoYn.hide();
        textbox1.setValue("");
    }

    if (scwin.gRow > -1 && scwin.gRow !=="") {
        scwin.detail();
    }

    $c.date.compareFromToDate(cal_prtdepoStrtDd, cal_prtdepoEndDd);
    $c.date.compareFromToDate(cal_miscPrtdepoStrtDd, cal_miscPrtdepoEndDd);

    scwin.filCodCtr();

    if ($c.session.getUserInfo("market") === '6') {
        panel_stk.hide()
    }

    // //2008-12-01 기타보호예수사유코드
    sbx_prtdepoObjKindCd.setValue(dma_prtdepo.get("prtdepoObjKindCd"));
    sbx_prtdepoPrnTpCd.setValue(dma_prtdepo.get("prtdepoPrnTpCd"));
    sbx_prtdepoRsnCd.setValue(dma_prtdepo.get("prtdepoRsnCd"));
    sbx_prtdepoRsnMngrghtTpCd.setValue(dma_prtdepo.get("prtdepoRsnMngrghtTpCd"));
    sbx_prtdepoRsnFncTpCd.setValue(dma_prtdepo.get("prtdepoRsnFncTpCd"));

    // //2008-12-05 기타보호예수사유 및 날짜 추가
    sbx_miscPrtdepoRsnCd.setValue(dma_prtdepo.get("miscPrtdepoRsnCd"));
    cal_miscPrtdepoStrtDd.setValue(dma_prtdepo.get("miscPrtdepoStrtDd"));
    cal_miscPrtdepoEndDd.setValue(dma_prtdepo.get("miscPrtdepoEndDd"));

    // 메인창의 저장,신규,삭제 버튼이 비활성화일 경우 보호예수도 수정불가
    if($c.win.getParent().scwin.btnStats !== "insert" && $c.win.getParent().scwin.btnStats !== "update"){
        $c.util.setButtonState("grpBtnBox", "error", scwin.BTN_MAP);
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_save_onclick
 * @description 저장 버튼
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function (e) {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92025.btn_save_onclick" });
    }
};

/**
 * @method
 * @name btn_delete_onclick
 * @description 삭제 버튼
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_delete_onclick = async function (e) {
    try {
        // gDtsObj.deleteRow(gDtsObj.rowposition);
        const paaramRtn = { "flag" : "D",
                             "seq" : scwin.gRow
                        }
        await $c.win.closePopup( paaramRtn );
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92025.btn_delete_onclick" });
    }
};

/**
 * @method
 * @name sbx_prtdepoObjKindCd_onchange
 * @description 의무보유대상종류 selectBox 1
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.sbx_prtdepoObjKindCd_onchange = function (info) {
    try {
        // sbx_prtdepoObjTpCd.removeColumnFilterAll();
        dlt_prtdepoObjTpCd.removeColumnFilterAll();

        if(info.newValue === "1"){ // 보통주
            sbx_prtdepoObjTpCd.setDisabled(true);
            dlt_prtdepoObjTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setSelectFilter, condition:"and"});
        }else if(info.newValue === "2"){
            sbx_prtdepoObjTpCd.setDisabled(false);
            dlt_prtdepoObjTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setSelectFilter2, condition:"and"});
        }else if(info.newValue === "3"){
            sbx_prtdepoObjTpCd.setDisabled(false);
            dlt_prtdepoObjTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setSelectFilter3, condition:"and"});
        }else{
            sbx_prtdepoObjTpCd.setDisabled(true);
            dlt_prtdepoObjTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setSelectFilter, condition:"and"});
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92025.sbx_prtdepoObjKindCd_onchange" });
    }
};

/**
 * @method
 * @name sbx_prtdepoRsnCd_onchange
 * @description 의무보유사유 selectBox 1
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.sbx_prtdepoRsnCd_onchange = function (info) {
    try {
        dlt_prtdepoRsnFncTpCd.removeColumnFilterAll();

        if (info.newValue === "61") {
            dlt_prtdepoRsnFncTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setprtSelectFilter, condition:"and"});
        }else if (info.newValue === "62"){
            dlt_prtdepoRsnFncTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setprtSelectFilter2, condition:"and"});
        }else if (info.newValue === "63") {
            dlt_prtdepoRsnFncTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setprtSelectFilter2, condition:"and"});
        }else if (info.newValue === "64") {
            dlt_prtdepoRsnFncTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setprtSelectFilter2, condition:"and"});
        }else if (info.newValue === "65") {
            dlt_prtdepoRsnFncTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setprtSelectFilter2, condition:"and"});
        }else if (info.newValue === "66") {
            dlt_prtdepoRsnFncTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setprtSelectFilter2, condition:"and"});
        }else if (info.newValue === "67") {
            dlt_prtdepoRsnFncTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setprtSelectFilter, condition:"and"});
        }else if (info.newValue === "68") {
            dlt_prtdepoRsnFncTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setprtSelectFilter3, condition:"and"});
        }else if (info.newValue === "69") {
            dlt_prtdepoRsnFncTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setprtSelectFilter, condition:"and"});
        }else if (info.newValue === "70") {
            dlt_prtdepoRsnFncTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setprtSelectFilter, condition:"and"});
        }else if (info.newValue === "71") {
            dlt_prtdepoRsnFncTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setprtSelectFilter2, condition:"and"});
        }else if (info.newValue === "72") {
            dlt_prtdepoRsnFncTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setprtSelectFilter2, condition:"and"});
        }else if (info.newValue === "73") {
            dlt_prtdepoRsnFncTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setprtSelectFilter2, condition:"and"});
        } else {
            // 유가는 다보여준다..
            dlt_prtdepoRsnFncTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setprtSelectFilter4, condition:"and"});
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92025.sbx_prtdepoRsnCd_onchange" });
    }
};

/**
 * @method
 * @name sbx_prtdepoObjTpCd_onchange
 * @description sbx_prtdepoObjTpCd 변경 이벤트
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.sbx_prtdepoObjTpCd_onchange = function (info) {
    try {
        if(info.newValue === "9"){
            ibx_prtdepoObjTpMiscContn.setReadOnly(false);
        }else{
            ibx_prtdepoObjTpMiscContn.setReadOnly(true);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92025.sbx_prtdepoObjTpCd_onchange" });
    }
};

/**
 * @method
 * @name sbx_prtdepoRsnFncTpCd_onchange
 * @description sbx_prtdepoRsnFncTpCd 변경 이벤트
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.sbx_prtdepoRsnFncTpCd_onchange = function (info) {
    try {
        sbx_prtdepoRsnMngrghtTpCd.setDisabled(true);
        dlt_prtdepoRsnMngrghtTpCd.removeColumnFilterAll();
        if (sbx_prtdepoRsnCd.getValue() === "01" || sbx_prtdepoRsnCd.getValue() === "62") {
            if (sbx_prtdepoRsnFncTpCd.getValue() === "1"){
                dlt_prtdepoRsnMngrghtTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setprtRsnSelectFilter, condition:"and"});
            }else if (sbx_prtdepoRsnFncTpCd.getValue() === "2") {
                sbx_prtdepoRsnMngrghtTpCd.setDisabled(false);
                dlt_prtdepoRsnMngrghtTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setprtRsnSelectFilter2, condition:"and"});
            }else {
                dlt_prtdepoRsnMngrghtTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setprtRsnSelectFilter, condition:"and"});
            }
        } else if (sbx_prtdepoRsnCd.getValue() === "02" || sbx_prtdepoRsnCd.getValue() === "63") {
            if (sbx_prtdepoRsnFncTpCd.getValue() === "1") {
                dlt_prtdepoRsnMngrghtTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setprtRsnSelectFilter, condition:"and"});
            }else if (sbx_prtdepoRsnFncTpCd.getValue() === "2") {
                sbx_prtdepoRsnMngrghtTpCd.setDisabled(false);
                dlt_prtdepoRsnMngrghtTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setprtRsnSelectFilter2, condition:"and"});
            }else {
                dlt_prtdepoRsnMngrghtTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setprtRsnSelectFilter, condition:"and"});
            }
        } else {
            dlt_prtdepoRsnMngrghtTpCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.setprtRsnSelectFilter, condition:"and"});
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92025.sbx_prtdepoRsnFncTpCd_onchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchCode
 * @description 공통코드 조회(콤보 항목 구성)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function () {
    // PRTDEPO_PRN_TP_CD => PRTDEPO_OBJ_TP_CD
    // PRTDEPO_RSN_FNC_TP_CD => PRTDEPO_RSN_MNGRGHT_TP_CD
    dma_codReq.set("codeList", "PRTDEPO_OBJ_KIND_CD, PRTDEPO_PRN_TP_CD, PRTDEPO_OBJ_TP_CD, PRTDEPO_RSN_CD, PRTDEPO_RSN_FNC_TP_CD, PRTDEPO_RSN_MNGRGHT_TP_CD, MISC_PRTDEPO_RSN_CD, KSD_DUTY_HD_CORR_STAT_CD"); // 코드정보 List
    const sbmOptions = {
        id: "sbm_listCodeValue",
        action: "/api/listing/common/code/list-code-value",
        method: "get",
        ref: "dma_codReq",
        target: "dlt_prtdepoObjKindCd=body.PRTDEPO_OBJ_KIND_CD, dlt_prtdepoPrnTpCd=body.PRTDEPO_PRN_TP_CD, dlt_prtdepoObjTpCd=body.PRTDEPO_OBJ_TP_CD"
            + ",dlt_prtdepoRsnCd=body.PRTDEPO_RSN_CD, dlt_prtdepoRsnMngrghtTpCd=body.PRTDEPO_RSN_FNC_TP_CD"
            + ",dlt_prtdepoRsnFncTpCd=body.PRTDEPO_RSN_MNGRGHT_TP_CD, dlt_miscPrtdepoRsnCd=body.MISC_PRTDEPO_RSN_CD, dlt_ksdDutyHdCorrStatCd=body.KSD_DUTY_HD_CORR_STAT_CD",
        // submitDoneHandler : scwin.sbm_listCodeValue_submitdone,
        isProcessMsg: false
    };
    await $c.sbm.executeDynamic(sbmOptions);
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name filCodCtr
 * @description 보호예수사유코드 세팅
 * @returns {void}
 * @hidden N
 */
scwin.filCodCtr = function () {
    if (scwin.market === '1') {
        // $c.pdc.fn_filCodCtr(sbx_prtdepoRsnCd, codArrRsnCod_U, undefined); // 보호예수사유코드
        dlt_prtdepoRsnCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.filCodCtrSelectFilter1, condition:"and"});
    } else if (scwin.market === '2' || scwin.market === '6') {
        // $c.pdc.fn_filCodCtr(sbx_prtdepoRsnCd, codArrRsnCod_K, undefined); // 보호예수사유코드
        dlt_prtdepoRsnCd.setColumnFilter({type:"func", colIndex:"value", key:scwin.filCodCtrSelectFilter2, condition:"and"});
    } else {
        dlt_prtdepoRsnCd.removeAll();
    }
};

/**
 * @method
 * @name filCodCtrSelectFilter1
 * @description 보호예수 사유코드 콤보 필터(유가 — 대상종류 1차)
 * @param {*} cellData cellData
 * @param {*} tmpParam tmpParam
 * @param {*} rowIdx rowIdx
 * @returns {Boolean}
 * @hidden N
 */
scwin.filCodCtrSelectFilter1 = function (cellData, tmpParam, rowIdx) {

    // codArrRsnCod_U =    [ // 유가 보호예수사유코드(PRTDEPO_RSN_CD)
    //     {cod: "01",  cap: "합병으로 인한 최대주주 변경등"},
    //     {cod: "02",  cap: "포괄적 주식교환으로 인한 최대주주 변경등"},
    //     {cod: "03",  cap: "영업양수 & 제3자배정으로 인한 최대주주 변경등"},
    //     {cod: "04",  cap: "자산양수 & 제3자배정으로 인한 최대주주 변경등"},
    //     {cod: "05",  cap: "주권비상장법인의 최대주주등으로부터 주식 취득 후 제3자배정으로 인한 최대주주 변경등"},
    //     {cod: "06",  cap: "제3자배정 & 주식납입으로 인한 최대주주 변경등"},
    //     {cod: "07",  cap: "제3자배정으로 인한 최대주주 변경"},
    //     {cod: "08",  cap: "관리종목 & 제3자배정"},
    //     {cod: "09",  cap: "거주자 외의 자 대상 해외 유가증권 발행 후 1년 이내 권리행사"},
    //     {cod: "10",  cap: "무상증자(의무보유기간중)"},
    //     {cod: "13",  cap: "주식매수선택권행사(의무보유 기간 중)"},
    //     {cod: "14",  cap: "주식등에 부여된 권리의 행사(의무보유 기간 중)"},
    //     {cod: "15",  cap: "주식배당(의무보유 기간 중)"},
    //     {cod: "11",  cap: "사모증자(감독원)"},
    //     {cod: "12",  cap: "자발적 의무보유"},
    //     {cod: "19",  cap: "기타"}
    //     ];

    if(cellData === "01" || cellData === "02" || cellData === "03" || cellData === "04" || cellData === "05" || cellData === "06"
        || cellData === "07" || cellData === "08" || cellData === "09" || cellData === "10" || cellData === "13" || cellData === "14"
        || cellData === "15" || cellData === "11" || cellData === "12" || cellData === "19"
    ){
        return true;
    }
    return false;   // true 인 경우 데이터에 포함, false 인 경우 데이터에서 제외
};

/**
 * @method
 * @name filCodCtrSelectFilter2
 * @description 보호예수 사유코드 콤보 필터(코스닥)
 * @param {*} cellData cellData
 * @param {*} tmpParam tmpParam
 * @param {*} rowIdx rowIdx
 * @returns {Boolean}
 * @hidden N
 */
scwin.filCodCtrSelectFilter2 = function (cellData, tmpParam, rowIdx) {
    // codArrRsnCod_K =    [ //  코스닥 보호예수사유코드(PRTDEPO_RSN_CD)
    //     {cod: "62",  cap: "합병"},
    //     {cod: "63",  cap: "포괄적주식교환"},
    //     {cod: "64",  cap: "영업양수&유상증자제3자배정"},
    //     {cod: "65",  cap: "자산양수&유상증자제3자배정"},
    //     {cod: "66",  cap: "주식스왑"},
    //     {cod: "71",  cap: "유상증자제3자배정에 따른 최대주주변경"},
    //     {cod: "72",  cap: "규정제50조제1항제2호 해당기업의 유상증자제3자배정"},
    //     {cod: "73",  cap: "무상증자(의무보유기간중)"},
    //     {cod: "68",  cap: "명목회사·조합 등으로의 최대주주 변경(코스닥시장 상장법인 인수시의 매각제한)"},
    //     {cod: "75",  cap: "주식매수선택권행사(의무보유 기간 중)"},
    //     {cod: "69",  cap: "기타"},
    //     {cod: "70",  cap: "해당사항 없음"}
    //     ];

    if(cellData === "62" || cellData === "63" || cellData === "64" || cellData === "65" || cellData === "66"
        || cellData === "71" || cellData === "72" || cellData === "73" || cellData === "68" || cellData === "75"
        || cellData === "69" || cellData === "70"
    ){
        return true;
    }
    return false;   // true 인 경우 데이터에 포함, false 인 경우 데이터에서 제외
};

/**
 * @method
 * @name detail
 * @description 그리드 선택 행(gDtsObj/gRow)의 의무보유 내역을 입력 폼에 반영
 * @returns {void}
 * @hidden N
 */
scwin.detail = function () {
    dma_prtdepo.set("seq", scwin.gDtsObj.getCellData(scwin.gRow, "seq"));
    dma_prtdepo.set("nm", scwin.gDtsObj.getCellData(scwin.gRow, "nm"));
    dma_prtdepo.set("resdbzRegNo", scwin.gDtsObj.getCellData(scwin.gRow, "resdbzRegNo"));
    dma_prtdepo.set("prtdepoShrs", scwin.gDtsObj.getCellData(scwin.gRow, "prtdepoShrs"));
    dma_prtdepo.set("prtdepoStrtDd", scwin.gDtsObj.getCellData(scwin.gRow, "prtdepoStrtDd"));
    dma_prtdepo.set("prtdepoEndDd", scwin.gDtsObj.getCellData(scwin.gRow, "prtdepoEndDd"));
    dma_prtdepo.set("prtdepoObjTpMiscContn", scwin.gDtsObj.getCellData(scwin.gRow, "prtdepoObjTpMiscContn"));
    dma_prtdepo.set("prtdepoPrnTpCd", scwin.gDtsObj.getCellData(scwin.gRow, "prtdepoPrnTpCd"));
    dma_prtdepo.set("prtdepoObjKindCd", scwin.gDtsObj.getCellData(scwin.gRow, "prtdepoObjKindCd"));
    dma_prtdepo.set("prtdepoObjTpCd", scwin.gDtsObj.getCellData(scwin.gRow, "prtdepoObjTpCd"));
    dma_prtdepo.set("prtdepoRsnCd", scwin.gDtsObj.getCellData(scwin.gRow, "prtdepoRsnCd"));
    dma_prtdepo.set("prtdepoRsnMngrghtTpCd", scwin.gDtsObj.getCellData(scwin.gRow, "prtdepoRsnMngrghtTpCd"));
    dma_prtdepo.set("prtdepoRsnFncTpCd", scwin.gDtsObj.getCellData(scwin.gRow, "prtdepoRsnFncTpCd"));

    // 2008-12-05 기타보호예수사유 및 날짜 추가
    dma_prtdepo.set("miscPrtdepoRsnCd", scwin.gDtsObj.getCellData(scwin.gRow, "miscPrtdepoRsnCd"));
    dma_prtdepo.set("miscPrtdepoStrtDd", scwin.gDtsObj.getCellData(scwin.gRow, "miscPrtdepoStrtDd"));
    dma_prtdepo.set("miscPrtdepoEndDd", scwin.gDtsObj.getCellData(scwin.gRow, "miscPrtdepoEndDd"));
};

/**
 * @method
 * @name checkForm
 * @description 저장/수정 전 입력값 검증(필수·형식·업무 규칙)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function () {
    // validation check//
    if (ibx_isuNm.getValue() === "") {
        await $c.win.alert("[종목]을 선택해주세요.");
        ibx_isuNm.focus();
        return false;
    }

    if (ibx_nm.getValue() === "") {
        await $c.win.alert("[성명] 을(를) 입력하셔야 합니다.");
        ibx_nm.focus();
        return false;
    }
    if (!$c.fil.checkMaxLength(ibx_nm, 80, "성명")) return false;
    if (ibx_resdbzRegNo.getValue() === "") {
        await $c.win.alert("[생년월일(사업자번호)] 을(를) 입력하셔야 합니다.");
        ibx_resdbzRegNo.focus();
        return false;
    }
    if (!$c.fil.checkMaxLength(ibx_resdbzRegNo, 20, "생년월일(사업자번호) ")) return false;
    if (ibx_prtdepoShrs.getValue() === "") {
        await $c.win.alert("[의무보유대상주식] 을(를) 입력하셔야 합니다.");
        ibx_prtdepoShrs.focus();
        return false;
    }
    if (sbx_prtdepoPrnTpCd.getValue() === "") {
        await $c.win.alert("[대상자구분] 을(를) 입력하셔야 합니다.");
        sbx_prtdepoPrnTpCd.focus();
        return false;
    }
    if (sbx_prtdepoObjKindCd.getValue() === "") {
        await $c.win.alert("[의무보유대상종류] 을(를) 입력하셔야 합니다.");
        sbx_prtdepoObjKindCd.focus();
        return false;
    }
    if (sbx_prtdepoRsnCd.getValue() === "") {
        await $c.win.alert("[의무보유사유] 을(를) 입력하셔야 합니다.");
        sbx_prtdepoRsnCd.focus();
        return false;
    }

    // 보호예수사유가 '해당사항없음' 일때 기간미입력하도록 변경 2009.04.14
    if (sbx_prtdepoRsnCd.getValue() === "70") {
        // 해당사항없음
        if (cal_prtdepoStrtDd.getValue() !== "") {
            await $c.win.alert("의무보유사유가 [해당사항없음] 일때는 의무보유기간을 입력하지 않습니다.");
            cal_prtdepoStrtDd.focus();
            return false;
        }
        if (cal_prtdepoEndDd.getValue() !== "") {
            await $c.win.alert("의무보유사유가 [해당사항없음] 일때는 의무보유기간을 입력하지 않습니다.");
            cal_prtdepoEndDd.focus();
            return false;
        }
    } else {
        if (cal_prtdepoStrtDd.getValue() === "") {
            await $c.win.alert("[의무보유시작일] 을(를) 입력하셔야 합니다.");
            cal_prtdepoStrtDd.focus();
            return false;
        }
        if (cal_prtdepoEndDd.getValue() === "") {
            await $c.win.alert("[의무보유종료일] 을(를) 입력하셔야 합니다.");
            cal_prtdepoEndDd.focus();
            return false;
        }
    }

    // 기타보호예수사유가 '해당사항없음' 일때 기간미입력하도록 변경 2009.04.14
    if (sbx_miscPrtdepoRsnCd.getValue() === "04") {
        // 해당사항없음
        if (cal_miscPrtdepoStrtDd.getValue() !== "") {
            await $c.win.alert("기타의무보유사유가 [해당사항없음] 일때는 기타의무보유기간을 입력하지 않습니다.");
            cal_miscPrtdepoStrtDd.focus();
            return false;
        }
        if (cal_miscPrtdepoEndDd.getValue() !== "") {
            await $c.win.alert("기타의무보유사유가 [해당사항없음] 일때는 기타의무보유기간을 입력하지 않습니다.");
            cal_miscPrtdepoEndDd.focus();
            return false;
        }
    }

    if (await scwin.dateCheck() === false) {
        return;
    }
    if (await scwin.dateCheckMisc() === false) {
        return;
    }
    return true;
};

/**
 * @method
 * @name dateCheck
 * @description 의무보유 시작일/종료일 선후 검사
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dateCheck = async function () {
    if (parseInt(cal_prtdepoStrtDd.getValue(), 10) > parseInt(cal_prtdepoEndDd.getValue(), 10)) {
        await $c.win.alert("[의무보유기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        cal_prtdepoStrtDd.setValue("");
        cal_prtdepoEndDd.setValue("");
        return false;
    }
};

/**
 * @method
 * @name dateCheckMisc
 * @description 기타 의무보유기간 시작일/종료일 선후 검사
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dateCheckMisc = async function () {
    if (parseInt(cal_miscPrtdepoStrtDd.getValue(), 10) > parseInt(cal_miscPrtdepoEndDd.getValue(), 10)) {
        await $c.win.alert("[기타의무보유기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        cal_miscPrtdepoStrtDd.setValue("");
        cal_miscPrtdepoEndDd.setValue("");
        return false;
    }
};

/**
 * @method
 * @name getCbTextValue
 * @description value 에 맞는 text 세팅
 * @param {Object} obj 컴포넌트
 * @returns {*}
 * @hidden N
 */
scwin.getCbTextValue = function (obj) {
    if (obj.getValue() === "") {
        return "";
    }
    return obj.getText();
};

/**
 * @method
 * @name save
 * @description 입력 검증·확인 후 의무보유 입력값을 오프너에 반환하고 팝업을 닫는다(저장 전송은 부모 화면)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function () {
    scwin.TR_JOB = 'I';
    if (!await scwin.checkForm()) return;
    // if (! fn_isProcess(TR_JOB) )  return ;
    const msg = " 팝업창이 닫히고, 메인창에서 저장을 수행해야 \n\n 정상적으로 의무보유 저장이 진행됩니다. \n 의무보유를 저장하시겠습니까?";
    let res = await $c.win.confirm(msg);
    if (res) {
        let resObj = {};
        resObj["prtdepoPrnTpCd"] = sbx_prtdepoPrnTpCd.getValue();
        resObj["prtdepoPrnTpNm"] = scwin.getCbTextValue(sbx_prtdepoPrnTpCd);
        resObj["prtdepoObjKindCd"] = sbx_prtdepoObjKindCd.getValue();
        resObj["prtdepoObjKindNm"] = scwin.getCbTextValue(sbx_prtdepoObjKindCd);
        resObj["prtdepoObjTpCd"] = sbx_prtdepoObjTpCd.getValue();
        resObj["prtdepoObjTpNm"] = scwin.getCbTextValue(sbx_prtdepoObjTpCd);
        resObj["prtdepoRsnCd"] = sbx_prtdepoRsnCd.getValue();
        resObj["prtdepoRsnNm"] = scwin.getCbTextValue(sbx_prtdepoRsnCd);
        resObj["prtdepoRsnMngrghtTpCd"] = sbx_prtdepoRsnMngrghtTpCd.getValue();
        resObj["prtdepoRsnMngrghtTpNm"] = scwin.getCbTextValue(sbx_prtdepoRsnMngrghtTpCd);
        resObj["prtdepoRsnFncTpCd"] = sbx_prtdepoRsnFncTpCd.getValue();
        resObj["prtdepoRsnFncTpNm"] = scwin.getCbTextValue(sbx_prtdepoRsnFncTpCd);
        resObj["nm"] = dma_prtdepo.get("nm");
        resObj["resdbzRegNo"] = dma_prtdepo.get("resdbzRegNo");
        resObj["prtdepoShrs"] = dma_prtdepo.get("prtdepoShrs");
        resObj["prtdepoStrtDd"] = dma_prtdepo.get("prtdepoStrtDd");
        resObj["prtdepoEndDd"] = dma_prtdepo.get("prtdepoEndDd");
        resObj["prtdepoObjTpMiscContn"] = dma_prtdepo.get("prtdepoObjTpMiscContn");

        // 2008-12-05 기타보호예수사유 및 날짜 추가
        resObj["miscPrtdepoRsnCd"] = sbx_miscPrtdepoRsnCd.getValue();
        resObj["miscPrtdepoStrtDd"] = cal_miscPrtdepoStrtDd.getValue();
        resObj["miscPrtdepoEndDd"] = cal_miscPrtdepoEndDd.getValue();
        resObj["prtdepoYn"] = sbx_prtdepoYn.getValue();
        await $c.win.closePopup(resObj);
    }
};

/**
 * @method
 * @name setSelectFilter
 * @description 셀렉트박스 필터 — 전부 제외(기본)
 * @param {*} cellData cellData
 * @param {*} tmpParam tmpParam
 * @param {*} rowIdx rowIdx
 * @returns {Boolean}
 * @hidden N
 */
scwin.setSelectFilter = function (cellData, tmpParam, rowIdx){
    return false;   // true 인 경우 데이터에 포함, false 인 경우 데이터에서 제외
};

/**
 * @method
 * @name setSelectFilter2
 * @description 셀렉트박스 필터 — 코드 1·2·3·9 만 포함
 * @param {*} cellData cellData
 * @param {*} tmpParam tmpParam
 * @param {*} rowIdx rowIdx
 * @returns {Boolean}
 * @hidden N
 */
scwin.setSelectFilter2 = function (cellData, tmpParam, rowIdx){
    if(cellData=== "1" || cellData === "2" || cellData === "3" || cellData === "9"){
        return true;
    }
    return false;   // true 인 경우 데이터에 포함, false 인 경우 데이터에서 제외
};

